0}, {"f": "wbt-railway-3.webp", "w": 800, "h": 1000}, {"f": "wbt-railway-4.webp", "w": 800, "h": 1000}, {"f": "wbt-railway-5.webp", "w": 800, "h": 1000}, {"f": "wbt-railway-6.webp", "w": 800, "h": 1000}], "title": "AI in Railway"}, {"slides": [{"f": "wbt-stadium-1.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-2.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-3.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-4.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-5.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-6.webp", "w": 800, "h": 1000}, {"f": "wbt-stadium-7.webp", "w": 800, "h": 1000}], "title": "AI in stadium"}, {"slides": [{"f": "wbt-edtech-1.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-2.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-3.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-4.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-5.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-6.webp", "w": 800, "h": 1000}, {"f": "wbt-edtech-7.webp", "w": 800, "h": 1000}], "title": "Edtech"}, {"slides": [{"f": "wbt-kumbh-1.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-2.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-3.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-4.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-5.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-6.webp", "w": 800, "h": 1000}, {"f": "wbt-kumbh-7.webp", "w": 800, "h": 1000}], "title": "mahakumbh"}], "posters": [{"f": "pos-theme.webp", "w": 1600, "h": 905, "k": "pos-theme"}, {"f": "pos-club-showcase.webp", "w": 562, "h": 1000, "k": "pos-club-showcase"}, {"f": "pos-recruitment-poster.webp", "w": 707, "h": 1000, "k": "pos-recruitment-poster"}, {"f": "pos-wbt-26-jan.webp", "w": 1000, "h": 1000, "k": "pos-wbt-26-jan"}], "logos": [{"f": "logo-foodicted.webp", "w": 500, "h": 500, "k": "logo-foodicted"}, {"f": "logo-wbt-logo.webp", "w": 1072, "h": 700, "k": "logo-wbt-logo"}, {"f": "logo-rishi-photography.webp", "w": 500, "h": 500, "k": "logo-rishi-photography"}]};
// a curated edit: the strongest pieces only, no near-duplicates and no plain lifestyle photos
const pick = (list, keys) => keys.map(k => list.find(it => it.k === k)).filter(Boolean);
const WORLDS = [
  { k: 'qodoro', name: 'Qodoro <em>Realty</em>', label: 'Qodoro Realty', kicker: 'Social campaign · Real estate',
    desc: 'Posts for a real-estate brand built on warm tones, editorial type and calm architecture and interiors, selling a feeling of home rather than square feet.',
    tags: ['Editorial layouts', 'Instagram posts', 'Brand guidelines'], bg: '#1A1818', fg: '#E8E4E0', acc: '#C4B0B0', items: pick(GD.qodoro, ['qod-1','qod-16','qod-17','qod-26','qod-27','qod-31','qod-32','qod-center','qod-left']) },
  { k: 'himspring', name: '<em>Himspring</em>', label: 'Himspring', kicker: 'Social campaign · Premium water',
    desc: 'A social campaign for a premium Himalayan water brand: cool light, clean headlines and quiet details that make a bottle of water feel like luxury.',
    tags: ['Art direction', 'Instagram posts', 'Brand voice'], bg: '#E8E4E0', fg: '#1A1818', acc: '#6B4F4F', items: pick(GD.himspring, ['him-27','him-28','him-31','him-32','him-33','him-37','him-43','him-44','him-45','him-47','him-49']) },
  { k: 'kallisto', name: 'Kallisto <em>Miorah</em>', label: 'Kallisto Miorah', kicker: 'Posts & stories · Fashion',
    desc: 'Posts and stories for a contemporary womenswear label: fashion-editorial layouts, product callouts and shop-the-look stories in soft, editorial tones.',
